def _report_tool(action: str, args: list[dict], fetch: "Callable[[], str]") -> str:
    """Call `fetch` and log the completed transition to the Quint oracle either way — the
    tool's own args plus a `remote` argument naming which of RemoteOutcome's four
    constructors this call landed in (quint-specs/mcp-webmcp-tools.qnt). Every tool below
